// RGB LED Pins
const int RED = 9;
const int GREEN = 10;
const int BLUE = 11;

void setup() {
  Serial.begin(9600);

  pinMode(RED, OUTPUT);
  pinMode(GREEN, OUTPUT);
  pinMode(BLUE, OUTPUT);

  Serial.println("Type a color:");
  Serial.println("red, green, blue, yellow, cyan, magenta, white, off");
}

void loop() {
  if (Serial.available()) {
    String color = Serial.readStringUntil('\n');
    color.trim();
    color.toLowerCase();

    if (color == "red") {
      setColor(255, 0, 0);
    }
    else if (color == "green") {
      setColor(0, 255, 0);
    }
    else if (color == "blue") {
      setColor(0, 0, 255);
    }
    else if (color == "yellow") {
      setColor(255, 255, 0);
    }
    else if (color == "cyan") {
      setColor(0, 255, 255);
    }
    else if (color == "magenta") {
      setColor(255, 0, 255);
    }
    else if (color == "white") {
      setColor(255, 255, 255);
    }
    else if (color == "off") {
      setColor(0, 0, 0);
    }
    else {
      Serial.println("Unknown color!");
      return;
    }

    Serial.print("Color set to: ");
    Serial.println(color);
  }
}

void setColor(int r, int g, int b) {
  analogWrite(RED, r);
  analogWrite(GREEN, g);
  analogWrite(BLUE, b);
}

