const float BETA = 3950.0;  // NTC B value
const float TEMP_LIMIT = 30.0; // Alarm temperature

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {

  // Read NTC sensor
  int analogValue = analogRead(TEMP_PIN);

  // Avoid division by zero
  if (analogValue == 0) {
    return;
  }

  float celsius = 1.0 /
                  (log(1.0 / (1023.0 / analogValue - 1.0)) / BETA +
                   1.0 / 298.15) -
                  273.15;

  Serial.print("Temperature: ");
  Serial.print(celsius);
  Serial.println(" °C");

  // Temperature alarm
  if (celsius >= TEMP_LIMIT) {

    int notes[] = {262, 294, 330, 349, 392, 440, 494, 523};
    int durs[]  = {200, 200, 200, 200, 200, 200, 200, 400};

    for (int i = 0; i < 8; i++) {
      tone(BUZZER_PIN, notes[i], durs[i]);
      delay(durs[i] + 30);
    }

    noTone(BUZZER_PIN);
  }
  else {
    noTone(BUZZER_PIN);
  }

  delay(500);
}

