#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

String message = "Hello, Arduino!";

void setup() {
  lcd.init();
  lcd.backlight();
}

void loop() {

  // Add spaces so the message completely leaves the screen
  String text = "                " + message + "                ";

  for (int i = 0; i <= text.length() - 16; i++) {

    lcd.setCursor(0, 0);

    // Print exactly 16 characters
    lcd.print(text.substring(i, i + 16));

    delay(200);
  }
}

