const int leds[] = {10, 11, 12, 13};

void setup() {
  for (int i = 0; i < 4; i++) {
    pinMode(leds[i], OUTPUT);
  }

  Serial.begin(9600);
}

void loop() {
  for (int count = 0; count < 16; count++) {

    // Display count in binary on LEDs
    for (int bit = 0; bit < 4; bit++) {
      digitalWrite(leds[bit], (count >> bit) & 1);
    }

    Serial.print("Count = ");
    Serial.print(count);
    Serial.print("  Binary = ");
    Serial.println(count, BIN);

    delay(1000);
  }
}

