#define PIN_R_1 11
#define PIN_G_1 10
#define PIN_B_1 9

void setup() {
  pinMode(PIN_R_1, OUTPUT);
  pinMode(PIN_G_1, OUTPUT);
  pinMode(PIN_B_1, OUTPUT);

  Serial.begin(9600);
}

void loop() {

  int val = analogRead(A0);

  // Convert ADC reading to voltage
  float voltage = val * (5.0 / 1023.0);

  // NTC calculation
  float resistance = 10000.0 * voltage / (5.0 - voltage);

  // Beta equation
  float beta = 3950.0;
  float R0 = 10000.0;
  float T0 = 298.15;

  float temperatureK =
      1.0 / ((1.0 / T0) + (1.0 / beta) * log(resistance / R0));

  float tempC = temperatureK - 273.15;

  Serial.print("Temperature: ");
  Serial.print(tempC);
  Serial.println(" C");

  // RGB
  if (tempC < 20) {
    // COLD → BLUE
    analogWrite(PIN_R_1, 0);
    analogWrite(PIN_G_1, 0);
    analogWrite(PIN_B_1, 255);
  }
  else if (tempC < 30) {
    // NORMAL → GREEN
    analogWrite(PIN_R_1, 0);
    analogWrite(PIN_G_1, 255);
    analogWrite(PIN_B_1, 0);
  }
  else {
    // HOT → RED
    analogWrite(PIN_R_1, 255);
    analogWrite(PIN_G_1, 0);
    analogWrite(PIN_B_1, 0);
  }

  delay(500);
}

