void setup() {
  Serial.begin(115200);

  pinMode(2, INPUT);
  pinMode(13, OUTPUT);

  Serial.println("MQ-2 Gas Sensor ready.");
}

void loop() {
  int analogVal = analogRead(A0);
  int digitalVal = digitalRead(2);

  Serial.print("MQ-2 AO: ");
  Serial.print(analogVal);
  Serial.print("  DO: ");
  Serial.println(digitalVal == LOW ? "GAS DETECTED" : "Clear");

  // Turn LED ON when analog value crosses threshold
  if (analogVal >= 300) {
    digitalWrite(13, HIGH);
  } else {
    digitalWrite(13, LOW);
  }

  delay(1000);
}

