#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

// =========================
// DHT22
// =========================
#define DHT_PIN 2
#define DHT_TYPE DHT22

DHT dht(DHT_PIN, DHT_TYPE);


// =========================
// LCD
// =========================
LiquidCrystal_I2C lcd(0x27, 16, 2);


// =========================
// Potentiometer
// =========================
#define POT_PIN A0


// =========================
// A4988
// =========================
#define STEP_PIN 8
#define DIR_PIN 9
#define ENABLE_PIN 10


// 1.8 degree stepper
const int STEPS_PER_REV = 200;


void setup() {

  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  pinMode(ENABLE_PIN, OUTPUT);

  digitalWrite(DIR_PIN, HIGH);

  // Enable A4988
  digitalWrite(ENABLE_PIN, LOW);

  dht.begin();

  lcd.init();
  lcd.backlight();

  lcd.setCursor(0, 0);
  lcd.print("Automatic Fan");

  lcd.setCursor(0, 1);
  lcd.print("Starting...");

  delay(2000);

  lcd.clear();

  Serial.begin(9600);
}


void loop() {

  // =========================
  // Read DHT22
  // =========================

  float temperature = dht.readTemperature();


  // =========================
  // Read potentiometer
  // =========================

  int potValue = analogRead(POT_PIN);


  // Convert pot to RPM
  // 0 -> 100
  int rpm = map(potValue, 0, 1023, 0, 100);

  rpm = constrain(rpm, 0, 100);


  // Debug information
  Serial.print("Temperature: ");
  Serial.print(temperature);

  Serial.print(" | Pot: ");
  Serial.print(potValue);

  Serial.print(" | RPM: ");
  Serial.println(rpm);


  // =========================
  // DHT ERROR
  // =========================

  if (isnan(temperature)) {

    digitalWrite(ENABLE_PIN, HIGH);
    digitalWrite(STEP_PIN, LOW);

    lcd.setCursor(0, 0);
    lcd.print("DHT22 ERROR     ");

    lcd.setCursor(0, 1);
    lcd.print("Fan: OFF        ");

    delay(1000);

    return;
  }


  // =========================
  // TEMP > 25°C
  // FAN ON
  // =========================

  if (temperature > 25) {

    // Enable driver
    digitalWrite(ENABLE_PIN, LOW);

    lcd.setCursor(0, 0);
    lcd.print("Fan: ON         ");

    lcd.setCursor(0, 1);
    lcd.print("Speed: ");
    lcd.print(rpm);
    lcd.print(" RPM    ");


    // Motor runs according to pot
    if (rpm > 0) {

      // Calculate steps per second
      float stepsPerSecond =
        (rpm * STEPS_PER_REV) / 60.0;


      // Time for one step
      unsigned long stepDelay =
        (unsigned long)(1000000.0 / stepsPerSecond);


      // STEP pulse
      digitalWrite(STEP_PIN, HIGH);
      delayMicroseconds(stepDelay / 2);

      digitalWrite(STEP_PIN, LOW);
      delayMicroseconds(stepDelay / 2);
    }
  }


  // =========================
  // TEMP <= 25°C
  // FAN OFF
  // =========================

  else {

    digitalWrite(ENABLE_PIN, HIGH);
    digitalWrite(STEP_PIN, LOW);

    lcd.setCursor(0, 0);
    lcd.print("Fan: OFF        ");

    lcd.setCursor(0, 1);
    lcd.print("Speed: ");
    lcd.print(rpm);
    lcd.print(" RPM    ");

    delay(100);
  }
}

