#include <DHT.h>
#include <LiquidCrystal_I2C.h>
#include <IRremote.hpp>
#include <Servo.h>

// =========================
// PIN DEFINITIONS
// =========================

#define PIR_PIN       2
#define SERVO_PIN     3
#define LDR_PIN       4
#define BUZZER_PIN    5
#define DHT_PIN       7
#define IR_PIN        8

#define RED_LED       12
#define YELLOW_LED    13

// =========================
// COMPONENT SETUP
// =========================

#define DHT_TYPE DHT22

DHT dht(DHT_PIN, DHT_TYPE);

LiquidCrystal_I2C lcd(0x27, 16, 2);

Servo doorServo;

// =========================
// VARIABLES
// =========================

bool automaticMode = true;

bool redLight = false;
bool yellowLight = false;

bool doorOpen = false;

unsigned long lastMotionTime = 0;

const unsigned long DOOR_OPEN_TIME = 5000;

// Temperature threshold
const float HIGH_TEMP = 30.0;

// =========================
// SETUP
// =========================

void setup() {

  Serial.begin(115200);

  // Pins
  pinMode(PIR_PIN, INPUT);
  pinMode(LDR_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  pinMode(RED_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);

  // Initial states
  digitalWrite(RED_LED, LOW);
  digitalWrite(YELLOW_LED, LOW);
  digitalWrite(BUZZER_PIN, LOW);

  // Servo
  doorServo.attach(SERVO_PIN);
  doorServo.write(0);

  // DHT
  dht.begin();

  // LCD
  lcd.init();
  lcd.backlight();

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("SMART HOME");
  lcd.setCursor(0, 1);
  lcd.print("Initializing...");

  // IR Receiver
  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);

  delay(2000);

  lcd.clear();

  Serial.println("======================");
  Serial.println(" SMART HOME SYSTEM");
  Serial.println("======================");
  Serial.println("System Ready!");

}


// =========================
// MAIN LOOP
// =========================

void loop() {

  // Read sensors
  int motion = digitalRead(PIR_PIN);
  int light = digitalRead(LDR_PIN);

  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();


  // =====================================
  // IR REMOTE CONTROL
  // =====================================

  if (IrReceiver.decode()) {

    unsigned long command =
      IrReceiver.decodedIRData.decodedRawData;

    Serial.print("IR Code: 0x");
    Serial.println(command, HEX);

    /*
       These codes depend on your remote.

       For now ANY button toggles automatic mode.
    */

    automaticMode = !automaticMode;

    Serial.print("Automatic Mode: ");

    if (automaticMode) {
      Serial.println("ON");
    } else {
      Serial.println("OFF");
    }

    IrReceiver.resume();
  }


  // =====================================
  // AUTOMATIC MODE
  // =====================================

  if (automaticMode) {

    // ---------------------------------
    // LDR + PIR → ROOM LIGHT
    // ---------------------------------

    /*
       Depending on the LDR module,
       DO can be HIGH or LOW in darkness.

       Most modules:
       LOW  = dark
       HIGH = bright
    */

    bool dark = (light == LOW);

    if (dark && motion == HIGH) {

      digitalWrite(RED_LED, HIGH);
      redLight = true;

    } else if (!motion) {

      digitalWrite(RED_LED, LOW);
      redLight = false;
    }


    // ---------------------------------
    // LDR → PORCH LIGHT
    // ---------------------------------

    if (dark) {

      digitalWrite(YELLOW_LED, HIGH);
      yellowLight = true;

    } else {

      digitalWrite(YELLOW_LED, LOW);
      yellowLight = false;
    }


    // ---------------------------------
    // PIR → AUTOMATIC DOOR
    // ---------------------------------

    if (motion == HIGH) {

      lastMotionTime = millis();

      if (!doorOpen) {

        doorServo.write(90);

        doorOpen = true;

        Serial.println("Door OPEN");
      }
    }


    // Close door after 5 seconds
    if (doorOpen &&
        millis() - lastMotionTime >= DOOR_OPEN_TIME) {

      doorServo.write(0);

      doorOpen = false;

      Serial.println("Door CLOSED");
    }


    // ---------------------------------
    // TEMPERATURE → BUZZER
    // ---------------------------------

    if (!isnan(temperature)) {

      if (temperature >= HIGH_TEMP) {

        digitalWrite(BUZZER_PIN, HIGH);

      } else {

        digitalWrite(BUZZER_PIN, LOW);
      }
    }
  }


  // =====================================
  // LCD DISPLAY
  // =====================================

  static unsigned long lastLCDUpdate = 0;

  if (millis() - lastLCDUpdate >= 1000) {

    lastLCDUpdate = millis();

    lcd.clear();

    // First line
    lcd.setCursor(0, 0);

    if (!isnan(temperature)) {

      lcd.print("T:");
      lcd.print(temperature, 1);
      lcd.print((char)223);
      lcd.print("C");

    } else {

      lcd.print("Temp: ERROR");
    }

    // Humidity
    if (!isnan(humidity)) {

      lcd.setCursor(9, 0);

      lcd.print("H:");
      lcd.print(humidity, 0);
      lcd.print("%");
    }


    // Second line
    lcd.setCursor(0, 1);

    lcd.print("M:");

    if (motion == HIGH) {
      lcd.print("YES ");
    } else {
      lcd.print("NO  ");
    }

    lcd.print("L:");

    if (redLight) {
      lcd.print("ON ");
    } else {
      lcd.print("OFF");
    }
  }


  // =====================================
  // SERIAL MONITOR
  // =====================================

  static unsigned long lastSerialUpdate = 0;

  if (millis() - lastSerialUpdate >= 2000) {

    lastSerialUpdate = millis();

    Serial.println("----------------------");

    Serial.print("Motion: ");
    Serial.println(motion ? "DETECTED" : "NONE");

    Serial.print("LDR: ");

    if (light == LOW) {
      Serial.println("DARK");
    } else {
      Serial.println("BRIGHT");
    }

    Serial.print("Temperature: ");

    if (!isnan(temperature)) {
      Serial.print(temperature);
      Serial.println(" C");
    } else {
      Serial.println("ERROR");
    }

    Serial.print("Humidity: ");

    if (!isnan(humidity)) {
      Serial.print(humidity);
      Serial.println(" %");
    } else {
      Serial.println("ERROR");
    }

    Serial.print("Room Light: ");
    Serial.println(redLight ? "ON" : "OFF");

    Serial.print("Porch Light: ");
    Serial.println(yellowLight ? "ON" : "OFF");

    Serial.print("Door: ");
    Serial.println(doorOpen ? "OPEN" : "CLOSED");

    Serial.print("Automatic Mode: ");
    Serial.println(automaticMode ? "ON" : "OFF");
  }

}

